Let $\varepsilon < r$ and $A^\varepsilon$ satisfy (1.1) and (2.14). Let $u_\varepsilon$ be a solution of
        \begin{equation}
    \left\{
    \begin{aligned}
        & -\nabla\cdot A^\varepsilon \nabla u_\varepsilon = 0 \quad \text{in } T_{3r}, \\
        & u_\varepsilon = f  \quad \text{on } I_{3r}.
    \end{aligned}
    \right.
    \end{equation}
    Then for any $\varepsilon < t< r$,
    \begin{equation}
        \frac{1}{t} \int_{T_r \cap \Omega_t} |\nabla u_\varepsilon|^2 \lesssim \int_{I_{3r}} |\nabla_{\tan} f|^2  + \frac{1}{r} \int_{T_{3r}} |\nabla u_\varepsilon|^2.
    \end{equation}
}

Let $\varepsilon < r$ and $A^\varepsilon$ satisfy (1.1) and (2.14). Let $u_\varepsilon$ be a solution of
        \begin{equation}
    \left\{
    \begin{aligned}
        & -\nabla\cdot A^\varepsilon \nabla u_\varepsilon = 0 \quad \text{in } T_{3r}, \\
        & \frac{\partial u_\varepsilon}{\partial \nu_\varepsilon} = g \quad \text{on } I_{3r}.
    \end{aligned}
    \right.
    \end{equation}
    Then for any $\varepsilon < t< r$,
    \begin{equation}
        \frac{1}{t} \int_{T_r \cap \Omega_t} |\nabla u_\varepsilon|^2 \lesssim \int_{I_{3r}} |g|^2  + \frac{1}{r} \int_{T_{3r}} |\nabla u_\varepsilon|^2.
    \end{equation}
}

Assume that $\Omega$ is a $C^1$ graph domain.
    Let $1\gtrsim r \gtrsim \varepsilon$. Let $u_\varepsilon$ be a weak solution of
    \begin{equation}
    \left\{
    \begin{aligned}
        & \mathcal{L}_\varepsilon(u_\varepsilon) = 0 \quad \text{in } T_{2r}, \\
        & u_\varepsilon = f \in W^{1,2}(I_{2r}) \quad \text{on } I_{2r}.
    \end{aligned}
    \right.
    \end{equation}
    Then for any $p\in [2,\infty)$ and $\varepsilon \le t < r$,
    \begin{equation}
        \bigg( \frac{1}{t} \int_{\Omega_t \cap T_{r/2}} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \lesssim \bigg( \int_{I_{2r}} |M_\varepsilon^\partial (\nabla_{\tan} f)|^p \bigg)^{1/p} + r^{\frac{d-1}{p} - \frac{d}{2}} \bigg( \int_{T_{2r}} |\nabla u_\varepsilon|^2 \bigg)^{1/2}.
    \end{equation}
}

Assume that $\Omega$ is a $C^1$ graph domain.
    Let $1\gtrsim r \gtrsim \varepsilon$. Let $u_\varepsilon$ be a weak solution of
    \begin{equation}
    \left\{
    \begin{aligned}
        & \mathcal{L}_\varepsilon(u_\varepsilon) = 0 \quad \text{in } T_{2r}, \\
        & \frac{\partial u_\varepsilon}{\partial \nu_\varepsilon} = g \in L^2(I_{2r}) \quad \text{on } I_{2r}.
    \end{aligned}
    \right.
    \end{equation}
    Then for any $p\in [2,\infty)$ and $\varepsilon \le t < r$,
    \begin{equation}
        \bigg( \frac{1}{t} \int_{\Omega_t \cap T_{r/2}} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \lesssim \bigg( \int_{I_{2r}} |M_\varepsilon^\partial (g)|^p \bigg)^{1/p} + r^{\frac{d-1}{p} - \frac{d}{2}} \bigg( \int_{T_{2r}} |\nabla u_\varepsilon|^2 \bigg)^{1/2}.
    \end{equation}
}

It holds $\overline{\omega}_\varepsilon^X \in B_2(d\sigma)$ uniformly in $\varepsilon$, in the sense that, any $r > 0, P\in \partial \Omega, X \in \Omega$ and $|X-P| > 5\max \{r, \varepsilon \}$,
    \begin{equation}
        \bigg( \fint_{\Delta_r(P)} \overline{\omega}_\varepsilon^X(Q)^2 d\sigma(Q) \bigg)^{1/2} \lesssim \fint_{\Delta_{r}(P)} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q).
    \end{equation}

Let $\Omega$ be a bounded $C^1$ domain. Then for any $p\in (2,\infty)$, we have $\overline{\omega}_\varepsilon^X \in B_p(d\sigma)$ uniformly in $\varepsilon$;  i.e., for any $r>0, P\in \partial \Omega, \Delta_r = \Delta_r(P)$ and $X\in \Omega\setminus B_{10r}(P)$
    \begin{equation}
        \bigg( \fint_{\Delta_r} \overline{\omega}_\varepsilon^X(Q)^p d\sigma(Q) \bigg)^{1/p} \lesssim \fint_{\Delta_{r}} \overline{\omega}_\varepsilon^X(Q) d\sigma(Q).
    \end{equation}

Let $\varepsilon \lesssim r$ and $I_r = I_r(O)$ with $O \in \partial \Omega$. Let $u_\varepsilon$ be a solution of $-\nabla\cdot A^\varepsilon \nabla u_\varepsilon = 0$ in $T_{10r}$.
    Then for any $Q = (z',\phi(z')) \in I_r$,






    \begin{equation}
    \begin{aligned}
        \widetilde{N}_\varepsilon^r(\nabla u_\varepsilon)(Q) &\lesssim \mathcal{M}_{I_{3r}} (\widetilde{N}_\varepsilon^{3r}(\mathcal{Q}_\varepsilon(u_\varepsilon)))(Q)  + \mathcal{M}_{I_{3r}} (V_\varepsilon)(Q),
    \end{aligned}
    \end{equation}
    where
\begin{equation}
    V_\varepsilon(P) = \fint_{0}^{11\varepsilon} |\nabla u_\varepsilon(y',\phi(y') + t)| dt, \ \text{with } P = (y',\phi(y')),
\end{equation}
    and
    \begin{equation}
        \mathcal{M}_{I_{3r}}f(Q) = \sup \bigg\{ \fint_{I'} |f| d\sigma: Q\in I' \subset I_{3r}\bigg\}.
    \end{equation}

Let $u_\varepsilon$ be a solution of $-\nabla\cdot A^\varepsilon \nabla u_\varepsilon = 0$ in $T_{5r}$ with $r \ge 10 \varepsilon$. Then
    \begin{equation}
    \int_{I_{r}} \widetilde{N}_\varepsilon^{r} (\mathcal{Q}_\varepsilon(u_\varepsilon))^2 d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{5r} \cap \Omega_{5\varepsilon}} |\nabla u_\varepsilon|^2 + \int_{T_{5r}} |\nabla u_\varepsilon|^2.
\end{equation}

Let $\Omega$ be a $C^1$ graph domain. Let $\mathcal{L}_\varepsilon(u_\varepsilon) = 0$ in $T_{10r}$, where $\varepsilon< r\le 1$. Then
    \begin{equation}
    \begin{aligned}
    \int_{I_r} |\widetilde{N}_\varepsilon^r(\nabla u_\varepsilon)|^p d\sigma \lesssim \frac{1}{\varepsilon} \int_{T_{10r} \cap \Omega_{20\varepsilon}} |M_\varepsilon(\nabla u_\varepsilon)|^p + \frac{1}{r} \int_{T_{10r}} |M_\varepsilon(\nabla u_\varepsilon)|^p.
    \end{aligned}
\end{equation}

\begin{equation}
    \mathcal{Q}_\varepsilon(u)(X) = \frac{ u(X + \varepsilon e_d) - u(X)}{\varepsilon} = \frac{1}{\varepsilon} \int_{x_d}^{x_d + \varepsilon} \frac{\partial u}{\partial x_d}(x',t) dt.
\end{equation}

\begin{equation}
    \bigg( \frac{1}{r} \int_{\Omega_r} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \le C  \| f \|_{H^1(\partial \Omega)},
\end{equation}

\begin{equation}
    \bigg( \frac{1}{r} \int_{\Omega_r} |\nabla u_\varepsilon|^2 \bigg)^{1/2} \le C \| g \|_{L^2(\partial \Omega)},
\end{equation}

Let $\Omega$ be a bounded $C^1$ domain.
Let $u_\varepsilon$ be a solution of (1.5) with $f\in W^{1,2}(\partial \Omega)$. Then for any $2<p<\infty$ and
 any $\varepsilon \le t < {\rm diam}(\Omega)$,
    \begin{equation}
        \bigg( \frac{1}{t} \int_{\Omega_t} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \lesssim \| M_\varepsilon^\partial(\nabla_{\tan} f) \|_{L^p(\partial \Omega)}.
    \end{equation}

Let $\Omega$ be a bounded $C^1$ domain.
Let $u_\varepsilon$ be a solution of (1.4) with $g\in L^2(\partial \Omega)$. Then for any $2<p<\infty$ and
 any $\varepsilon \le t < {\rm diam}(\Omega)$,
    \begin{equation}
        \bigg( \frac{1}{t} \int_{\Omega_t} |M_\varepsilon(\nabla u_\varepsilon)|^p \bigg)^{1/p} \lesssim \| M_\varepsilon^\partial(g) \|_{L^p(\partial \Omega)}.
    \end{equation}
